"""
Builds the fourth coefficient matrix A2 (32x32) from A3 (a previous step's output) and the fixed perturbation matrix M3, applying a correction only when needed so that A2 - A3 ends up positive semidefinite.

Builds the fourth coefficient matrix $A_2$ from $A_3$ (a previous step's output) and a fixed perturbation matrix $M_3$, applying a correction only when needed so that $A_2 - A_3$ ends up positive semidefinite.










Formulas:










$A_{2,0} = \operatorname{symmetrize}(A_3 + 1.5I + 0.05M_3)$, where $\operatorname{symmetrize}(Y) = (Y + Y^{T})/2$










Let $d = \lambda_{\min}(A_{2,0} - A_3)$.










If $d < 0$: $A_2 = A_{2,0} - dI + 10^{-6}I$










Else: $A_2 = A_{2,0}$

Returns
-------
A2 : np.ndarray of shape (32,32), the symmetric matrix with A2 - A3 positive semidefinite.
"""

# =============================================================================
# FUNCTION SIGNATURE (shown to the LLM)
# =============================================================================

import numpy as np


def build_matrix_A2(A3: np.ndarray, M3: np.ndarray) -> np.ndarray:
    """Build A2 from A3 and M3 so that A2 - A3 is positive semidefinite.

    Parameters
    ----------
    A3 : np.ndarray
        (32, 32) real symmetric positive definite matrix.
    M3 : np.ndarray
        (32, 32) real matrix.

    Returns
    -------
    A2 : np.ndarray
        (32, 32) real symmetric matrix with A2 - A3 positive semidefinite.

    Raises
    ------
    ValueError
        If A3 or M3 does not have shape (32, 32).
    """
    A2 = np.eye(32)  # placeholder
    return A2

# =============================================================================
# GOLD SOLUTION
# =============================================================================

import numpy as np


def _oracle_build_matrix_A2(A3: np.ndarray, M3: np.ndarray) -> np.ndarray:
    A3 = np.asarray(A3, dtype=float)
    M3 = np.asarray(M3, dtype=float)
    if A3.shape != (32, 32) or M3.shape != (32, 32):
        raise ValueError("A3 and M3 must have shape (32,32)")
    n = 32
    A2_0 = A3 + 1.5 * np.eye(n) + 0.05 * M3
    A2_0 = 0.5 * (A2_0 + A2_0.T)
    d = np.linalg.eigvalsh(A2_0 - A3).min()
    if d < 0:
        A2 = A2_0 - d * np.eye(n) + 1e-6 * np.eye(n)
    else:
        A2 = A2_0
    return A2

